#include <bits/stdc++.h>
using namespace std;
class Solution {public:int maximumsSplicedArray(vector<int>& nums1,vector<int>& nums2){long long s1=0,s2=0,cur1=0,cur2=0,best1=0,best2=0;for(int i=0;i<(int)nums1.size();++i){s1+=nums1[i];s2+=nums2[i];long long d=nums2[i]-nums1[i];cur1=max(0LL,cur1+d);best1=max(best1,cur1);cur2=max(0LL,cur2-d);best2=max(best2,cur2);}return max(s1+best1,s2+best2);}};
